mapper.select:
select m.id, m.title, m.status, m.sort_order as sortOrder, m.user_id as userId from mes_rec_introspect m
m.deleted_flag = 0 and m.user_id = #{param.userId}
and m.id = #{param.id}
and m.title like concat('%', #{param.title}, '%')
and m.status = #{param.status}
order by m.status asc, m.sort_order asc, m.update_time desc
